begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $native$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1746 then raise exception 'NATIVE_CAMPAIGN_CHANGED';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:283d43a7fbb28f2f5d081a4d' and md5(to_jsonb(t)::text)='fcd3782dc3a18c3d0c8ef13a3ecd4344')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:283d43a7fbb28f2f5d081a4d';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_4537d306067d5a9a${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:283d43a7fbb28f2f5d081a4d","revision":1,"language":"es","name":"Varita de las maravillas","aliases":["Varita de la Maravilla"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:0c16e43cf556110e7edfb0c34ae9eeef74d98d241b1988667092d46b878b7cad","kind":"legacy","title":"Varita de la Maravilla","language":"es","rulesEdition":null,"locator":"official:equipment:es:283d43a7fbb28f2f5d081a4d","verified":false},{"id":"original:794d36ecc6be15239a572277497702e0e3d2dffbbddf02ff8168a4b9f2ad4dd0","kind":"legacy","title":"Varita de la Maravilla","language":"es","rulesEdition":null,"locator":"official:equipment:es:283d43a7fbb28f2f5d081a4d","verified":false},{"id":"original:f8373fddc560ca1e0369ffac435e984e66405bb81c071bcb04343b02045552e9","kind":"legacy","title":"Wand of Wonder","language":"en","rulesEdition":null,"locator":"official:equipment:eng:ba5465888af88d416c2d2705","verified":false},{"id":"original:0adf17cca8a001338e33cde6bbb61f23cb7274c47b2bffb8fabfbc94eb809876","kind":"legacy","title":"Wand of Wonder","language":"en","rulesEdition":null,"locator":"official:equipment:eng:ba5465888af88d416c2d2705","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"SRD 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 267 · CC BY 4.0","verified":true}],"category":"wand","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":[],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":""},"description":[{"id":"official-block-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 de sus cargas y elegir un objetivo a 36 m o menos de ti. El objetivo puede ser una criatura, un objeto o un punto en el espacio. Tira 1d100 y consulta la tabla que aparece a continuación para descubrir lo que ocurrirá."},{"id":"official-block-1","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Si el efecto hace que lances un conjuro con la varita, la CD de salvación será 15. Si el conjuro tiene normalmente un alcance expresado en metros, su alcance pasará a ser de 36 m (si no lo era ya)."},{"id":"official-block-2","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Si un efecto cubre un área, deberás centrar el conjuro en el objetivo e incluirlo en su interior. Si un efecto tiene varios objetivos posibles, tu GM determinará al azar cuáles se verán afectados."},{"id":"official-block-3","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"La varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en polvo y se destruye."},{"id":"official-block-4","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"table","columns":["d100","Efecto"],"rows":[["01–05","Lanzas ralentizar."],["06–10","Lanzas fuego feérico."],["11–15","Crees que algo asombroso acaba de ocurrir, por lo que te quedas aturdido hasta el principio de tu siguiente turno."],["16–20","Lanzas ráfaga de viento."],["21–25","Lanzas detectar pensamientos sobre el objetivo que elijas. Si no has hecho objetivo a una criatura, en vez de eso, recibirás 1d6 de daño psíquico."],["26–30","Lanzas nube apestosa."],["31–33","Una lluvia intensa cae en un radio de 18 m centrado en el objetivo. La zona se vuelve ligeramente oscura. La lluvia cae hasta el principio de tu siguiente turno."],["34–36","Un animal aparece en el espacio sin ocupar más cercano al objetivo. El animal no se encuentra bajo tu control y actúa con normalidad. Tira 1d100 para determinar qué animal aparece. Si el resultado es 01-25, aparecerá un rinoceronte; si es 26-50, aparecerá un elefante, y con 51-100, aparecerá una rata."],["37–46","Lanzas relámpago."],["47–49","Una nube de 600 mariposas de gran tamaño cubre un radio de 9 m centrado en el objetivo. La zona se vuelve muy oscura. Las mariposas permanecen durante 10 minutos."],["50–53","Aumentas el tamaño del objetivo como si hubieras lanzado agrandar/reducir. Si el objetivo no puede verse afectado por ese conjuro o si no has hecho objetivo a una criatura, tú te convertirás en el objetivo."],["54–58","Lanzas oscuridad."],["59–62","La hierba crece en el suelo en un radio de 18 m centrado en el objetivo. Si ya había hierba allí, crecerá hasta diez veces su tamaño normal y tendrá ese tamaño durante 1 minuto."],["63–65","Un objeto a elección de tu GM desaparece en el Plano Etéreo. El objeto no puede medir más de 3 m en ninguna dimensión, debe encontrarse a 36 m o menos del objetivo y nadie puede vestirlo o llevarlo."],["66–69","Encoges como si hubieras lanzado agrandar/reducir sobre ti."],["70–79","Lanzas bola de fuego."],["80–84","Lanzas invisibilidad sobre ti."],["85–87","Crecen hojas en el objetivo. Si eliges un punto en el espacio como objetivo, las hojas brotan de la criatura más cercana a ese punto. Salvo que se arranquen, las hojas se volverán marrones y caerán tras 24 horas."],["88–90","Una ráfaga de 1d4 × 10 gemas, cada una con un valor de 1 po, sale disparada de la punta de la varita en una línea de 9 m de largo y 1,5 m de ancho. Cada gema hace 1 de daño contundente y el total de daño de las gemas se divide a partes iguales entre todas las criaturas situadas en la línea."],["91–95","Una explosión de luz resplandeciente y colorida se extiende desde ti en un radio de 9 m. Todas las criaturas que puedan ver en el área y tú deberéis superar una tirada de salvación de Constitución con CD 15 o quedaréis cegados durante 1 minuto. Una criatura puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto."],["96–97","La piel del objetivo se vuelve azul brillante durante 1d10 días. Si has elegido un punto en el espacio como objetivo, la criatura más cercana a ese punto será quien sufra el efecto."],["98–00","Si tu objetivo es una criatura, deberá hacer una tirada de salvación de Constitución con CD 15. Si no has hecho objetivo a una criatura, tú te convertirás en el objetivo y deberás hacer la tirada de salvación. Si la falla por 5 o más, el objetivo quedará petrificado instantáneamente. Si la falla con otro resultado, el objetivo quedará apresado y comenzará a convertirse en piedra. Mientras el objetivo esté apresado de esta forma, deberá repetir la tirada de salvación al final de su siguiente turno; quedará petrificado si la falla o se librará del efecto si la supera. La petrificación dura hasta que el objetivo sea liberado mediante un conjuro restablecimiento mayor u otro efecto mágico similar."]]}],"requirements":{"attunement":true,"bearer":[{"kind":"spellcaster","keys":[],"explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"}],"presence":"held","explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"},"weapon":null,"armor":null,"resources":[{"id":"charges","name":"Cargas","kind":"charges","maximum":7,"unit":"cargas","recovery":{"kind":"event","event":"dawn","explanation":"Recuperación indicada por la fuente al amanecer.","amount":{"kind":"roll","expression":"1d6+1"}},"exhaustion":"Aplicar las consecuencias particulares de la descripción cuando se gasten sus cargas."}],"capabilities":[{"id":"official-2014-rule","name":"Reglas de la variante","activation":"other","trigger":"","requirements":{"attunement":true,"bearer":[{"kind":"spellcaster","keys":[],"explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"}],"presence":"held","explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"},"target":"Según la regla oficial.","range":"","duration":"Según la regla oficial.","concentration":"spell-dependent","costs":[],"consumeQuantity":0,"effects":[{"id":"source-rule","condition":"","kind":"unmodeled","explanation":"Resolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.","original":{"index":"wand-of-wonder","source":"srd-5.1-es-equipment","subtype":null}}],"execution":{"mode":"assisted","handler":"equipment-text-assistance","explanation":"Descripción y variante cotejadas. El consumo de una poción se registra; el resto de efectos y gastos se resuelve según la regla concreta.","pendingAutomation":["Conectar las elecciones, objetivos, costes variables, duración y efectos particulares de esta regla.","Registrar los gastos reales de cargas y resolver las consecuencias de la última carga según la descripción."]},"textBlockIds":["official-block-0","official-block-1","official-block-2","official-block-3","official-block-4"]},{"id":"last-charge-check","name":"Última carga","activation":"trigger","trigger":"Al gastar la última carga del objeto.","requirements":{"attunement":true,"bearer":[{"kind":"spellcaster","keys":[],"explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"}],"presence":"held","explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"},"target":"El objeto","range":"","duration":"Instantánea","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"destroy-on-one","kind":"last-charge-destruction","condition":"Después de gastar la última carga.","sides":20,"destroyAtOrBelow":1}],"execution":{"mode":"automatic","handler":"equipment-last-charge","explanation":"Registra la comprobación pendiente y retira únicamente el ejemplar destruido al resolver el d20. La recarga queda bloqueada hasta resolverla.","pendingAutomation":[]},"textBlockIds":["official-block-3"]}],"recoverySourceIds":["0c16e43cf556110e7edfb0c34ae9eeef74d98d241b1988667092d46b878b7cad","794d36ecc6be15239a572277497702e0e3d2dffbbddf02ff8168a4b9f2ad4dd0","f8373fddc560ca1e0369ffac435e984e66405bb81c071bcb04343b02045552e9","0adf17cca8a001338e33cde6bbb61f23cb7274c47b2bffb8fabfbc94eb809876"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Conservar originales y cerrar su recuperación antes de eliminar versiones."]}}$native_4537d306067d5a9a$::jsonb,true),'{features}',$native_9e343969c674a850$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 de sus cargas y elegir un objetivo a 36 m o menos de ti. El objetivo puede ser una criatura, un objeto o un punto en el espacio. Tira 1d100 y consulta la tabla que aparece a continuación para descubrir lo que ocurrirá.\n\nSi el efecto hace que lances un conjuro con la varita, la CD de salvación será 15. Si el conjuro tiene normalmente un alcance expresado en metros, su alcance pasará a ser de 36 m (si no lo era ya).\n\nSi un efecto cubre un área, deberás centrar el conjuro en el objetivo e incluirlo en su interior. Si un efecto tiene varios objetivos posibles, tu GM determinará al azar cuáles se verán afectados.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en polvo y se destruye.\n\n01–05 · Lanzas ralentizar.\n06–10 · Lanzas fuego feérico.\n11–15 · Crees que algo asombroso acaba de ocurrir, por lo que te quedas aturdido hasta el principio de tu siguiente turno.\n16–20 · Lanzas ráfaga de viento.\n21–25 · Lanzas detectar pensamientos sobre el objetivo que elijas. Si no has hecho objetivo a una criatura, en vez de eso, recibirás 1d6 de daño psíquico.\n26–30 · Lanzas nube apestosa.\n31–33 · Una lluvia intensa cae en un radio de 18 m centrado en el objetivo. La zona se vuelve ligeramente oscura. La lluvia cae hasta el principio de tu siguiente turno.\n34–36 · Un animal aparece en el espacio sin ocupar más cercano al objetivo. El animal no se encuentra bajo tu control y actúa con normalidad. Tira 1d100 para determinar qué animal aparece. Si el resultado es 01-25, aparecerá un rinoceronte; si es 26-50, aparecerá un elefante, y con 51-100, aparecerá una rata.\n37–46 · Lanzas relámpago.\n47–49 · Una nube de 600 mariposas de gran tamaño cubre un radio de 9 m centrado en el objetivo. La zona se vuelve muy oscura. Las mariposas permanecen durante 10 minutos.\n50–53 · Aumentas el tamaño del objetivo como si hubieras lanzado agrandar/reducir. Si el objetivo no puede verse afectado por ese conjuro o si no has hecho objetivo a una criatura, tú te convertirás en el objetivo.\n54–58 · Lanzas oscuridad.\n59–62 · La hierba crece en el suelo en un radio de 18 m centrado en el objetivo. Si ya había hierba allí, crecerá hasta diez veces su tamaño normal y tendrá ese tamaño durante 1 minuto.\n63–65 · Un objeto a elección de tu GM desaparece en el Plano Etéreo. El objeto no puede medir más de 3 m en ninguna dimensión, debe encontrarse a 36 m o menos del objetivo y nadie puede vestirlo o llevarlo.\n66–69 · Encoges como si hubieras lanzado agrandar/reducir sobre ti.\n70–79 · Lanzas bola de fuego.\n80–84 · Lanzas invisibilidad sobre ti.\n85–87 · Crecen hojas en el objetivo. Si eliges un punto en el espacio como objetivo, las hojas brotan de la criatura más cercana a ese punto. Salvo que se arranquen, las hojas se volverán marrones y caerán tras 24 horas.\n88–90 · Una ráfaga de 1d4 × 10 gemas, cada una con un valor de 1 po, sale disparada de la punta de la varita en una línea de 9 m de largo y 1,5 m de ancho. Cada gema hace 1 de daño contundente y el total de daño de las gemas se divide a partes iguales entre todas las criaturas situadas en la línea.\n91–95 · Una explosión de luz resplandeciente y colorida se extiende desde ti en un radio de 9 m. Todas las criaturas que puedan ver en el área y tú deberéis superar una tirada de salvación de Constitución con CD 15 o quedaréis cegados durante 1 minuto. Una criatura puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n96–97 · La piel del objetivo se vuelve azul brillante durante 1d10 días. Si has elegido un punto en el espacio como objetivo, la criatura más cercana a ese punto será quien sufra el efecto.\n98–00 · Si tu objetivo es una criatura, deberá hacer una tirada de salvación de Constitución con CD 15. Si no has hecho objetivo a una criatura, tú te convertirás en el objetivo y deberás hacer la tirada de salvación. Si la falla por 5 o más, el objetivo quedará petrificado instantáneamente. Si la falla con otro resultado, el objetivo quedará apresado y comenzará a convertirse en piedra. Mientras el objetivo esté apresado de esta forma, deberá repetir la tirada de salvación al final de su siguiente turno; quedará petrificado si la falla o se librará del efecto si la supera. La petrificación dura hasta que el objetivo sea liberado mediante un conjuro restablecimiento mayor u otro efecto mágico similar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$native_9e343969c674a850$::jsonb,true),'{charges}',$native_8f2cbb085ea12f62${"reset":"manual","current":7,"maximum":7}$native_8f2cbb085ea12f62$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:283d43a7fbb28f2f5d081a4d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:285015c1f803ed9cd52a94c8' and md5(to_jsonb(t)::text)='5238293d8448b90b7e40a96492885392')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:285015c1f803ed9cd52a94c8';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_6261b08b6f69c156${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:285015c1f803ed9cd52a94c8","revision":1,"language":"es","name":"Varita de parálisis","aliases":[],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:118b7fff9582418b9e638e720bba5e5e082170122f8670dcfd8747c664fa7cb6","kind":"legacy","title":"Varita de parálisis","language":"es","rulesEdition":null,"locator":"official:equipment:es:285015c1f803ed9cd52a94c8","verified":false},{"id":"original:0deb6acb11ed70b7986daebb29352f05036f28948b981f0d91eed4c38d4f8be1","kind":"legacy","title":"Varita de parálisis","language":"es","rulesEdition":null,"locator":"official:equipment:es:285015c1f803ed9cd52a94c8","verified":false},{"id":"original:dc0319ce81a04f0d2ddab8f7c79b8c1e7f679b99b42eacfefa33dd0107f766e8","kind":"legacy","title":"Wand of Paralysis","language":"en","rulesEdition":null,"locator":"official:equipment:eng:dd18fb408ab8a1a8a1ab6e4b","verified":false},{"id":"original:88fab5357ed43ecf30ef19b89dc6cb7e07980e2dd6f6b88e63c1231c2bdd15c1","kind":"legacy","title":"Wand of Paralysis","language":"en","rulesEdition":null,"locator":"official:equipment:eng:dd18fb408ab8a1a8a1ab6e4b","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"Documento de referencia del sistema 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 268 · CC BY 4.0","verified":true}],"category":"wand","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":[],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":""},"description":[{"id":"official-rule-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para conjurar un delgado rayo azul que serpenteará desde la punta de la varita hacia una criatura que puedas ver a 18 m o menos de ti. El objetivo deberá superar una tirada de salvación de Constitución con CD 15 o quedará paralizado durante 1 minuto. Podrá repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto."},{"id":"official-rule-1","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"La varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye."}],"requirements":{"attunement":true,"bearer":[{"kind":"spellcaster","keys":[],"explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"}],"presence":"held","explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"official-assisted-rule","name":"Reglas del objeto","activation":"other","trigger":"","requirements":{"attunement":true,"bearer":[{"kind":"spellcaster","keys":[],"explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"}],"presence":"held","explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"},"target":"Según la regla oficial.","range":"","duration":"Según la regla oficial.","concentration":"spell-dependent","costs":[],"consumeQuantity":0,"effects":[{"id":"assisted-rule","condition":"","kind":"unmodeled","explanation":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para conjurar un delgado rayo azul que serpenteará desde la punta de la varita hacia una criatura que puedas ver a 18 m o menos de ti. El objetivo deberá superar una tirada de salvación de Constitución con CD 15 o quedará paralizado durante 1 minuto. Podrá repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.","original":{"page":268,"source":"srd-5.1-es-equipment","metadata":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"}}],"execution":{"mode":"assisted","handler":"equipment-text-assistance","explanation":"Consultar la regla oficial y resolver los efectos descritos en la mesa; no concede activaciones ni recuperaciones automáticas.","pendingAutomation":["Conectar los costes, objetivos, duración y efectos particulares de esta regla antes de habilitar su uso automático."]},"textBlockIds":["official-rule-0","official-rule-1"]},{"id":"last-charge-check","name":"Última carga","activation":"trigger","trigger":"Al gastar la última carga del objeto.","requirements":{"attunement":true,"bearer":[{"kind":"spellcaster","keys":[],"explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"}],"presence":"held","explanation":"Varita, rara (requiere sintonización por parte de un lanzador de conjuros)"},"target":"El objeto","range":"","duration":"Instantánea","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"destroy-on-one","kind":"last-charge-destruction","condition":"Después de gastar la última carga.","sides":20,"destroyAtOrBelow":1}],"execution":{"mode":"automatic","handler":"equipment-last-charge","explanation":"Registra la comprobación pendiente y retira únicamente el ejemplar destruido al resolver el d20. La recarga queda bloqueada hasta resolverla.","pendingAutomation":[]},"textBlockIds":["official-rule-1"]}],"recoverySourceIds":["118b7fff9582418b9e638e720bba5e5e082170122f8670dcfd8747c664fa7cb6","0deb6acb11ed70b7986daebb29352f05036f28948b981f0d91eed4c38d4f8be1","dc0319ce81a04f0d2ddab8f7c79b8c1e7f679b99b42eacfefa33dd0107f766e8","88fab5357ed43ecf30ef19b89dc6cb7e07980e2dd6f6b88e63c1231c2bdd15c1"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["La descripción oficial española está recuperada íntegramente; faltan adaptar y validar las mecánicas particulares y cerrar la cobertura de todos los campos originales."]}}$native_6261b08b6f69c156$::jsonb,true),'{features}',$native_1d722e423b49351b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para conjurar un delgado rayo azul que serpenteará desde la punta de la varita hacia una criatura que puedas ver a 18 m o menos de ti. El objetivo deberá superar una tirada de salvación de Constitución con CD 15 o quedará paralizado durante 1 minuto. Podrá repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$native_1d722e423b49351b$::jsonb,true),'{charges}',$native_522893c3a1fb6e18${"reset":"at-dawn","current":7,"maximum":7}$native_522893c3a1fb6e18$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:285015c1f803ed9cd52a94c8';
