perties":[],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":""},"description":[{"id":"xanathar-text-0","section":"rules","provenance":"reviewed-translation","sourceIds":["xanathar-supplied-es"],"type":"paragraph","text":"Este bastón de madera tiene 10 cargas. Mientras lo sostienes, puedes usar una acción para gastar 1 carga del bastón y hacer que brote una flor de un trozo de tierra a 5 pies de ti, o del propio bastón. A menos que elijas un tipo específico de flor, el bastón crea una margarita de aroma suave. La flor es inofensiva y no mágica, y crece o se marchita como lo haría una flor normal."},{"id":"xanathar-text-1","section":"rules","provenance":"reviewed-translation","sourceIds":["xanathar-supplied-es"],"type":"paragraph","text":"El bastón recupera ld6 + 4 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira un d20. En un 1, el bastón se convierte en pétalos de flores y se pierde para siempre."}],"requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"Bastón, común"},"weapon":null,"armor":null,"resources":[{"id":"item-uses","name":"Cargas","kind":"charges","maximum":10,"unit":"cargas","recovery":{"kind":"event","event":"dawn","explanation":"Recupera al amanecer, no con un descanso.","amount":{"kind":"roll","expression":"1d6+4"}},"exhaustion":"Al gastar la última carga, resolver la tirada y consecuencia indicadas en la descripción; no destruir ni transformar automáticamente."}],"capabilities":[{"id":"xanathar-property","name":"Activar propiedad","activation":"action","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"Bastón, común"},"target":"Según la descripción del objeto.","range":"","duration":"Según la descripción del objeto.","concentration":false,"costs":[{"resourceId":"item-uses","amount":1}],"consumeQuantity":0,"effects":[{"id":"xanathar-narrative","condition":"","kind":"narrative","instructions":"Resolver el efecto descrito en la mesa. La interfaz registra sus costes y su recuperación cuando corresponda."}],"execution":{"mode":"assisted","handler":"equipment-text-assistance","explanation":"Texto transcrito del manual aportado; los costes y la recuperación configurados se registran en la copia. Las elecciones y efectos externos se resuelven según el texto.","pendingAutomation":["Aplicar las pruebas, elecciones, objetivos y efectos externos que especifica la descripción.","Resolver la tirada por la última carga y su destrucción o transformación."]},"textBlockIds":["xanathar-text-0","xanathar-text-1"]},{"id":"last-charge-check","name":"Última carga","activation":"trigger","trigger":"Al gastar la última carga del objeto.","requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"Bastón, común"},"target":"El objeto","range":"","duration":"Instantánea","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"destroy-on-one","kind":"last-charge-destruction","condition":"Después de gastar la última carga.","sides":20,"destroyAtOrBelow":1}],"execution":{"mode":"automatic","handler":"equipment-last-charge","explanation":"Registra la comprobación pendiente y retira únicamente el ejemplar destruido al resolver el d20. La recarga queda bloqueada hasta resolverla.","pendingAutomation":[]},"textBlockIds":["xanathar-text-1"]}],"recoverySourceIds":["491fd674d90f21e72643e44700c92c9edced219fc916c0b6761a762120bb768f","6249e2d638145c914749d792d1f8a041e0b6af0044a1a56dfacac38b96600ae5","f78f5b57668dd3a0724d75dc8e45ae3274ae74e73c172f6de4452751d81f7b58","5b2e267e5520c9c0fed971ddbe739246c0606d55887ed0229d75a25b4e48752f"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":true,"unresolved":["Transcripción fiel del documento aportado; acreditar o sustituir por la traducción editorial oficial si se obtiene.","Conservar originales y cerrar su cobertura antes de eliminar versiones."]}}$native_1553e2ca20c2e4ce$::jsonb,true),'{features}',$native_7b80c3c99125377f$[{"id":"xanathar-property","kind":"action","name":"Activar propiedad","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Este bastón de madera tiene 10 cargas. Mientras lo sostienes, puedes usar una acción para gastar 1 carga del bastón y hacer que brote una flor de un trozo de tierra a 5 pies de ti, o del propio bastón. A menos que elijas un tipo específico de flor, el bastón crea una margarita de aroma suave. La flor es inofensiva y no mágica, y crece o se marchita como lo haría una flor normal.\n\nEl bastón recupera ld6 + 4 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira un d20. En un 1, el bastón se convierte en pétalos de flores y se pierde para siempre.\n\nResolver el efecto descrito en la mesa. La interfaz registra sus costes y su recuperación cuando corresponda.\n\nDuración: Según la descripción del objeto..\n\nCoste: 1 Cargas.","showInActions":true}]$native_7b80c3c99125377f$::jsonb,true),'{charges}',$native_45b436819bc8a817${"reset":"manual","current":10,"maximum":10}$native_45b436819bc8a817$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3197a4c13048be4426d6c7a7';
