if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8e74acfe2a0c28dcf4c90bd9' and md5(to_jsonb(t)::text)='c878be299dcc5478147806ffc5e26eec')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:8e74acfe2a0c28dcf4c90bd9';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_3570f09742ece9f1${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:8e74acfe2a0c28dcf4c90bd9","revision":1,"language":"es","name":"Varita del terror","aliases":["Varita del miedo"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:4b995013ed19a9276d2ed3d90c0d0efe565af61f130b4fba89aa87c07ad3d270","kind":"legacy","title":"Varita del miedo","language":"es","rulesEdition":null,"locator":"official:equipment:es:8e74acfe2a0c28dcf4c90bd9","verified":false},{"id":"original:43b7aec61ffca4a6cf501d9498a9ea1e87dfc742a12148e9942542f60df8824e","kind":"legacy","title":"Varita del miedo","language":"es","rulesEdition":null,"locator":"official:equipment:es:8e74acfe2a0c28dcf4c90bd9","verified":false},{"id":"original:803bae58d34143b6a1b34501f34dba53789125e3c95abbea97439c7e6863edd4","kind":"legacy","title":"Wand of Fear","language":"en","rulesEdition":null,"locator":"official:equipment:eng:4da3de6dd906224cd5747afc","verified":false},{"id":"original:67ae1bf43e27d3bd1aadefec3077838a9cf07e411374fc67b525e166bba484db","kind":"legacy","title":"Wand of Fear","language":"en","rulesEdition":null,"locator":"official:equipment:eng:4da3de6dd906224cd5747afc","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"SRD 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 269 · CC BY 4.0","verified":true}],"category":"wand","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":[],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":""},"description":[{"id":"official-block-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Esta varita tiene 7 cargas para utilizar las propiedades que se describen a continuación. Recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye."},{"id":"official-block-1","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Cono de terror. Mientras empuñes la varita, podrás usar una acción y gastar 2 cargas para que la punta de la varita emita un cono de 18 m de luz ámbar. Todas las criaturas situadas en el cono deberán superar una tirada de salvación de Sabiduría con CD 15 o quedarán asustadas de ti durante 1 minuto. Una criatura asustada de esta manera deberá dedicar sus turnos a tratar de alejarse de ti todo lo que pueda y no podrá acercarse voluntariamente a ningún espacio que se encuentre a 9 m o menos de ti. Tampoco podrá llevar a cabo reacciones. Tan solo podrá realizar la acción de correr o intentar escapar de un efecto que le impida moverse. Si no tiene adónde ir, la criatura podrá usar la acción de esquivar. Al final de cada uno de sus turnos, la criatura podrá repetir la tirada de salvación y, si tiene éxito, se librará del efecto."},{"id":"official-block-2","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Orden. Mientras empuñes la varita, podrás usar una acción para gastar 1 carga y ordenar a otra criatura que huya o se postre, como con el conjuro orden imperiosa (CD de salvación de conjuros 15)."}],"requirements":{"attunement":true,"bearer":[],"presence":"held","explanation":"Varita, rara (requiere sintonización)"},"weapon":null,"armor":null,"resources":[{"id":"charges","